def parse_html_block(html_text, gender_tag):
    pattern = re.compile(r'<img[^>]+alt="([^"]+)"[^>]+src="([^"]+)"', re.IGNORECASE)
    matches = pattern.findall(html_text)
    results = []
    for alt, src in matches:
        clean_name = html.unescape(alt).strip()
        results.append({    
            "name": clean_name,
            "url": src.strip(),
            "gender": gender_tag
        })
    return results

list1 = parse_html_block(block1, "Women / General")
list2 = parse_html_block(block2, "Men / Short")

print(f"Parsed {len(list1)} items from list 1 (Women / General)")
print(f"Parsed {len(list2)} items from list 2 (Men / Short)")

# Save parsed json
all_items = list1 + list2
with open("hairstyles_data.json", "w", encoding="utf-8") as f:
    json.dump(all_items, f, indent=2, ensure_ascii=False)

print(f"Total: {len(all_items)} hairstyles written to hairstyles_data.json")

# Database Insertion / Sync
init_db()
db = SessionLocal()
try:
    # First, let's remove any old placeholder sample hairstyles or existing ones to ensure clean sync
    # Or upsert by b2_url / name
    inserted_count = 0
    updated_count = 0

    for idx, item in enumerate(all_items):
        url = item["url"]
        name = item["name"]
        gender = item["gender"]
        
        # Check if asset with this URL or name exists in category hairstyle
        existing = db.query(Asset).filter(
            Asset.category == "hairstyle",
            (Asset.b2_url == url)
        ).first()

        meta = json.dumps({"gender": gender, "collection": "women" if "Women" in gender else "men"})
        key = f"cdn_hair_{idx+1}_{name.lower().replace(' ', '_').replace('&', 'and')}"

        if existing:
            existing.name = name
            existing.b2_url = url
            existing.thumbnail_url = url
            existing.meta_json = meta
            updated_count += 1
        else:
            new_asset = Asset(
                category="hairstyle",
                name=name,
                b2_key=key,
                b2_url=url,
                thumbnail_url=url,
                meta_json=meta
            )
            db.add(new_asset)
            inserted_count += 1

    db.commit()
    print(f"Sync complete: {inserted_count} inserted, {updated_count} updated.")
    total_db_hairstyles = db.query(Asset).filter(Asset.category == "hairstyle").count()
    print(f"Total hairstyles in DB now: {total_db_hairstyles}")

finally:
    db.close()
